window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9fa1d5bf1e5c55f7"]={"versions": [{"id": "FIG-9fa1d5bf1e5c55f7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden-Aktivitäts- und Datenflussdiagramm (AUTOSAR Methodology Activity Diagram) aus der AUTOSAR Classic Platform Spezifikation <code>AUTOSAR_TR_Methodology</code>. Das Diagramm modelliert den methodischen Teilschritt „Configure Com“ innerhalb des übergeordneten Entwicklungsprozesses der Steuergeräte- und Basissoftware-Konfiguration (ECU Configuration / Configure BSW). Es spezifiziert die Beziehungen zwischen der Aktivität, der zuständigen Entwicklerrolle sowie den erforderlichen Eingangs- und resultierenden Ausgangs-Artefakten zur Parametrierung des AUTOSAR COM-Moduls (Communication).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Configure Com</strong>: Zentrale Aktivität (Aktivitätsknoten) zur Konfiguration und Parametrierung des AUTOSAR COM-Stacks.</li>\n<li><strong>ECU Integrator</strong>: Durchführende Rolle (Kardinalität <code>1</code>, Assoziationsstereotyp <code>«performs»</code>), verantwortlich für die Integration und Konfiguration der Basissoftware auf Steuergeräteebene.</li>\n<li><strong>ECU Extract</strong> [of System Description]: Verbindliches Eingangsartefakt (Kardinalität <code>1</code>, Stereotyp <code>«input»</code>), das den steuergerätespezifischen Auszug der Kommunikationsmatrix (Signale, I-PDUs, Frames, Bus-Cluster, Signaleigenschaften) enthält.</li>\n<li><strong>BSW Module Delivered Bundle</strong>: Optionales Eingangsartefakt (Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>), welches die herstellerspezifische Modullieferung des COM-Treibers/Stacks inklusive BSW Module Description (BSWMD / Parameterdefinitionen) umfasst.</li>\n<li><strong>AUTOSAR Standardized ECU</strong> [Configuration Definition]: Optionales standardisiertes Eingangsartefakt (Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>), welches die standardisierten AUTOSAR-Parameterdefinitionen für das COM-Modul bereitstellt.</li>\n<li><strong>ECU Configuration Values</strong>: Ein-/Ausgangsartefakt (Kardinalität <code>1</code>, Stereotyp <code>«inoutput»</code>), repräsentiert das ARXML-Modell der Steuergeräte-Konfigurationswerte (<code>EcucValueCollection</code>), das als Ausgangsbasis dient und um die COM-spezifischen Konfigurationscontainer (z. B. <code>ComGeneral</code>, <code>ComConfig</code>, <code>ComSignal</code>, <code>ComIPdu</code>) aktualisiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Artefaktbereitstellung</strong>: Die Aktivität setzt das Vorhandensein eines konsistenten <code>ECU Extract</code> voraus, der die Kommunikationsanforderungen der SWCs und Netzwerke definiert. Ergänzend werden die BSW-Parameterdefinitionen entweder aus dem <code>BSW Module Delivered Bundle</code> oder der <code>AUTOSAR Standardized ECU</code> Konfigurationsdefinition herangezogen.</li>\n<li><strong>Konfigurationsprozess</strong>: Der <code>ECU Integrator</code> lädt die bestehenden <code>ECU Configuration Values</code> sowie den <code>ECU Extract</code> in das ECU-Konfigurationswerkzeug. Die Kommunikationssignale und I-PDUs des Systemauszugs werden den internen Datenstrukturen des COM-Moduls zugeordnet (Signal- und PDU-Routing, Transfer Properties, Filter, Timeouts, Sendemodi).</li>\n<li><strong>Ergebnis</strong>: Die Aktivität aktualisiert das Artefakt <code>ECU Configuration Values</code> bidirektional (<code>«inoutput»</code>) mit den validierten COM-Parametern für die nachgelagerte BSW- und RTE-Codegenerierung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Obwohl im Technical Report (<code>AUTOSAR_TR_Methodology</code>) verankert, besitzen die dargestellten Datenflüsse und Abhängigkeiten normative Verbindlichkeit für die Interoperabilität von AUTOSAR-Werkzeugketten. Die Kardinalität <code>0..1</code> bei <code>BSW Module Delivered Bundle</code> und <code>AUTOSAR Standardized ECU</code> spiegelt wider, dass Toolketten entweder gegen vendor-spezifische BSWMD-Definitionen oder gegen die standardisierten AUTOSAR-Metamodell-Definitionen arbeiten können. Das Stereotyp <code>«inoutput»</code> an <code>ECU Configuration Values</code> verdeutlicht das inkrementelle Vorgehen: Vorhandene Steuergeräte-Konfigurationswerte bleiben erhalten und werden um modulspezifische COM-Container erweitert, ohne vorherige Konfigurationen zu überschreiben.</p>"}, {"id": "FIG-15edb2e0cd984b47", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden-Aktivitäts- und Datenflussdiagramm (AUTOSAR Methodology Activity Diagram) aus der AUTOSAR Classic Platform Spezifikation <code>AUTOSAR_TR_Methodology</code>. Das Diagramm modelliert den methodischen Teilschritt „Configure Com“ innerhalb des übergeordneten Entwicklungsprozesses der Steuergeräte- und Basissoftware-Konfiguration (ECU Configuration / Configure BSW). Es spezifiziert die Beziehungen zwischen der Aktivität, der zuständigen Entwicklerrolle sowie den erforderlichen Eingangs- und resultierenden Ausgangs-Artefakten zur Parametrierung des AUTOSAR COM-Moduls (Communication).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Configure Com</strong>: Zentrale Aktivität (Aktivitätsknoten) zur Konfiguration und Parametrierung des AUTOSAR COM-Stacks.</li>\n<li><strong>ECU Integrator</strong>: Durchführende Rolle (Kardinalität <code>1</code>, Assoziationsstereotyp <code>«performs»</code>), verantwortlich für die Integration und Konfiguration der Basissoftware auf Steuergeräteebene.</li>\n<li><strong>ECU Extract</strong> [of System Description]: Verbindliches Eingangsartefakt (Kardinalität <code>1</code>, Stereotyp <code>«input»</code>), das den steuergerätespezifischen Auszug der Kommunikationsmatrix (Signale, I-PDUs, Frames, Bus-Cluster, Signaleigenschaften) enthält.</li>\n<li><strong>BSW Module Delivered Bundle</strong>: Optionales Eingangsartefakt (Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>), welches die herstellerspezifische Modullieferung des COM-Treibers/Stacks inklusive BSW Module Description (BSWMD / Parameterdefinitionen) umfasst.</li>\n<li><strong>AUTOSAR Standardized ECU</strong> [Configuration Definition]: Optionales standardisiertes Eingangsartefakt (Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>), welches die standardisierten AUTOSAR-Parameterdefinitionen für das COM-Modul bereitstellt.</li>\n<li><strong>ECU Configuration Values</strong>: Ein-/Ausgangsartefakt (Kardinalität <code>1</code>, Stereotyp <code>«inoutput»</code>), repräsentiert das ARXML-Modell der Steuergeräte-Konfigurationswerte (<code>EcucValueCollection</code>), das als Ausgangsbasis dient und um die COM-spezifischen Konfigurationscontainer (z. B. <code>ComGeneral</code>, <code>ComConfig</code>, <code>ComSignal</code>, <code>ComIPdu</code>) aktualisiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Artefaktbereitstellung</strong>: Die Aktivität setzt das Vorhandensein eines konsistenten <code>ECU Extract</code> voraus, der die Kommunikationsanforderungen der SWCs und Netzwerke definiert. Ergänzend werden die BSW-Parameterdefinitionen entweder aus dem <code>BSW Module Delivered Bundle</code> oder der <code>AUTOSAR Standardized ECU</code> Konfigurationsdefinition herangezogen.</li>\n<li><strong>Konfigurationsprozess</strong>: Der <code>ECU Integrator</code> lädt die bestehenden <code>ECU Configuration Values</code> sowie den <code>ECU Extract</code> in das ECU-Konfigurationswerkzeug. Die Kommunikationssignale und I-PDUs des Systemauszugs werden den internen Datenstrukturen des COM-Moduls zugeordnet (Signal- und PDU-Routing, Transfer Properties, Filter, Timeouts, Sendemodi).</li>\n<li><strong>Ergebnis</strong>: Die Aktivität aktualisiert das Artefakt <code>ECU Configuration Values</code> bidirektional (<code>«inoutput»</code>) mit den validierten COM-Parametern für die nachgelagerte BSW- und RTE-Codegenerierung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Obwohl im Technical Report (<code>AUTOSAR_TR_Methodology</code>) verankert, besitzen die dargestellten Datenflüsse und Abhängigkeiten normative Verbindlichkeit für die Interoperabilität von AUTOSAR-Werkzeugketten. Die Kardinalität <code>0..1</code> bei <code>BSW Module Delivered Bundle</code> und <code>AUTOSAR Standardized ECU</code> spiegelt wider, dass Toolketten entweder gegen vendor-spezifische BSWMD-Definitionen oder gegen die standardisierten AUTOSAR-Metamodell-Definitionen arbeiten können. Das Stereotyp <code>«inoutput»</code> an <code>ECU Configuration Values</code> verdeutlicht das inkrementelle Vorgehen: Vorhandene Steuergeräte-Konfigurationswerte bleiben erhalten und werden um modulspezifische COM-Container erweitert, ohne vorherige Konfigurationen zu überschreiben.</p>"}], "trans": [{"from": "FIG-9fa1d5bf1e5c55f7", "to": "FIG-15edb2e0cd984b47", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
